-- V90.p Recipe/BOM and Material Requirement Engine
CREATE TABLE IF NOT EXISTS recipe (recipe_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, product_master_id TEXT NOT NULL, recipe_code TEXT NOT NULL, recipe_name TEXT NOT NULL, version_no INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'DRAFT', effective_from TEXT, effective_to TEXT, yield_qty NUMERIC NOT NULL DEFAULT 100, yield_uom TEXT NOT NULL DEFAULT 'kg', expected_loss_pct NUMERIC NOT NULL DEFAULT 0, notes TEXT, created_by TEXT NOT NULL, approved_by TEXT, approved_at TEXT, approval_reason TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS ux_recipe_code_version ON recipe(organization_id, entity_id, recipe_code, version_no);
CREATE TABLE IF NOT EXISTS recipe_line (recipe_line_id TEXT PRIMARY KEY, recipe_id TEXT NOT NULL, line_no INTEGER NOT NULL, material_master_id TEXT NOT NULL, material_type TEXT NOT NULL DEFAULT 'RAW_MATERIAL', qty NUMERIC NOT NULL, uom TEXT NOT NULL, scrap_pct NUMERIC NOT NULL DEFAULT 0, notes TEXT, FOREIGN KEY(recipe_id) REFERENCES recipe(recipe_id));
CREATE TABLE IF NOT EXISTS recipe_packaging_line (recipe_packaging_line_id TEXT PRIMARY KEY, recipe_id TEXT NOT NULL, line_no INTEGER NOT NULL, packaging_master_id TEXT NOT NULL, qty NUMERIC NOT NULL, uom TEXT NOT NULL, notes TEXT, FOREIGN KEY(recipe_id) REFERENCES recipe(recipe_id));
CREATE TABLE IF NOT EXISTS material_requirement_calc (calc_id TEXT PRIMARY KEY, plan_id TEXT NOT NULL, plan_line_id TEXT NOT NULL, recipe_id TEXT NOT NULL, material_master_id TEXT NOT NULL, requirement_type TEXT NOT NULL, gross_qty NUMERIC NOT NULL, scrap_qty NUMERIC NOT NULL DEFAULT 0, required_qty NUMERIC NOT NULL, uom TEXT NOT NULL, available_qty NUMERIC, shortage_qty NUMERIC, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
